VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
BLOCK_TAGS = {"p", "h1", "h2", "h3", "h4", "h5", "h6", "ul", "ol", "li", "blockquote", "pre", "div", "table", "tr", "hr"}

class Node:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.parent = parent
        self.children = []

    def add_child(self, node):
        self.children.append(node)

    def text_content(self):
        return "".join(c.text_content() for c in self.children)

class TextNode(Node):
    def __init__(self, text, parent=None):
        super().__init__(None, None, parent)
        self.text = text

    def text_content(self):
        return self.text

class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.root = Node(None)
        self.current = self.root

    def handle_starttag(self, tag, attrs):
        node = Node(tag, dict(attrs), self.current)
        self.current.add_child(node)
        if tag not in VOID_TAGS:
            self.current = node

    def handle_endtag(self, tag):
        curr = self.current
        while curr and curr.tag != tag:
            curr = curr.parent
        if curr and curr.parent:
            self.current = curr.parent

    def handle_startendtag(self, tag, attrs):
        node = Node(tag, dict(attrs), self.current)
        self.current.add_child(node)

    def handle_data(self, data):
        self.current.add_child(TextNode(data, self.current))

class Converter:
    def __init__(self, args):
        self.args = args
        self.domain = args.domain

    def convert(self, node):
        return self._render(node)

    def _render(self, node):
        if isinstance(node, TextNode):
            return node.text
        return "".join(self._render(c) for c in node.children)

