    parser.add_argument("--opt-table-skip-empty-rows", action="store_true")
    parser.add_argument("--opt-table-span-cell-behavior", default="mirror")
    parser.add_argument("--plugin-strikethrough", action="store_true")
    parser.add_argument("--plugin-table", action="store_true")

