import argparse
import sys
import os
import glob
import re
from urllib.parse import urljoin
from html.parser import HTMLParser

VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}

class Node:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower() if tag else tag
        self.attrs = attrs or {}
        self.parent = parent
        self.children = []
    def add_child(self, node):
        self.children.append(node)

class TextNode(Node):
    def __init__(self, text, parent=None):
        super().__init__(None, None, parent)
        self.text = text

class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.root = Node(None)
        self.current = self.root

    def handle_starttag(self, tag, attrs):
        node = Node(tag, dict(attrs), self.current)
        self.current.add_child(node)
        if tag.lower() not in VOID_TAGS:
            self.current = node

    def handle_endtag(self, tag):
        tag = tag.lower()
        curr = self.current
        while curr and curr.tag != tag:
            curr = curr.parent
        if curr and curr.parent:
            self.current = curr.parent

    def handle_startendtag(self, tag, attrs):
        node = Node(tag, dict(attrs), self.current)
        self.current.add_child(node)

    def handle_data(self, data):
        self.current.add_child(TextNode(data, self.current))

def parse_html(html):
    p = Parser()
    p.feed(html)
    return p.root

def collapse_whitespace(text):
    return re.sub(r'\s+', ' ', text)

def escape_text(text, is_start_of_line=False):
    # escapes \ ` * _ [
    # if start of line, also escape # + - . > (wait, > becomes &gt;)
    text = text.replace('\\', '\\\\')
    text = text.replace('`', '\\`')
    text = text.replace('*', '\\*')
    text = text.replace('_', '\\_')
    text = text.replace('[', '\\[')

    if is_start_of_line:
        if text.startswith('#'):
            text = '\\' + text
        elif text.startswith('+'):
            text = '\\' + text
        elif text.startswith('-'):
            text = '\\' + text
        elif text.startswith('1.'): # approximation
            text = text.replace('.', '\\.', 1)
        if text.startswith('>'):
            text = '&gt;' + text[1:]

    # replace < and > in middle
    text = text.replace('<', '&lt;')
    text = text.replace('>', '&gt;')
    return text

def render_node(node, ctx, is_start_of_line=False):
    if isinstance(node, TextNode):
        return escape_text(collapse_whitespace(node.text), is_start_of_line)

    if node.tag in ['head', 'style', 'script', 'meta', 'link', 'title']:
        return ""

    inner = "".join(render_node(c, ctx) for c in node.children)

    if node.tag in ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']:
        level = int(node.tag[1])
        return f"{'#' * level} {inner.strip()}\n\n"

    if node.tag == 'p':
        return f"{inner.strip()}\n\n"

    if node.tag == 'br':
        return "  \n"

    if node.tag == 'hr':
        return "* * *\n\n"

    if node.tag in ['strong', 'b']:
        delim = ctx.args.opt_strong_delimiter
        return f"{delim}{inner.strip()}{delim}"

    if node.tag in ['em', 'i']:
        return f"*{inner.strip()}*"

    if node.tag == 'a':
        href = node.attrs.get('href', '')
        if ctx.args.domain:
            href = urljoin(ctx.args.domain, href)
        title = node.attrs.get('title')
        if title:
            return f"[{inner.strip()}]({href} \"{title}\")"
        return f"[{inner.strip()}]({href})"

    if node.tag == 'img':
        src = node.attrs.get('src', '')
        if ctx.args.domain:
            src = urljoin(ctx.args.domain, src)
        alt = node.attrs.get('alt', '')
        title = node.attrs.get('title')
        if title:
            return f"![{alt}]({src} \"{title}\")"
        return f"![{alt}]({src})"

    if node.tag == 'code':
        return f"`{inner}`"

    if node.tag == 'pre':
        lang = ""
        if node.children and node.children[0].tag == 'code':
            cls = node.children[0].attrs.get('class', '')
            if cls.startswith('language-'):
                lang = cls[9:]
            inner = "".join(c.text if isinstance(c, TextNode) else c.text for c in node.children[0].children) # simplification
        else:
            inner = "".join(c.text if isinstance(c, TextNode) else "" for c in node.children)
        return f"```{lang}\n{inner}\n```\n\n"

    if node.tag == 'blockquote':
        lines = inner.strip().split('\n')
        res = "\n".join(f"> {line}" if line else "> " for line in lines)
        return res + "\n\n"

    if node.tag == 'ul':
        res = ""
        for c in node.children:
            if c.tag == 'li':
                item_inner = render_node(c, ctx).strip()
                lines = item_inner.split('\n')
                res += f"- {lines[0]}\n"
                for line in lines[1:]:
                    res += f"  {line}\n"
        return res + "\n"

    if node.tag == 'ol':
        res = ""
        i = 1
        for c in node.children:
            if c.tag == 'li':
                item_inner = render_node(c, ctx).strip()
                lines = item_inner.split('\n')
                res += f"{i}. {lines[0]}\n"
                for line in lines[1:]:
                    res += f"   {line}\n" # 3 spaces for ol?
                i += 1
        return res + "\n"

    if node.tag in ['del', 's', 'strike']:
        if getattr(ctx.args, 'plugin_strikethrough', False):
            return f"~~{inner.strip()}~~"
        return inner

    if node.tag == 'table':
        if not getattr(ctx.args, 'plugin_table', False):
            # fallback: just text
            return inner
        # simple markdown table (not fully respecting all options yet)
        return render_table(node, ctx)

    return inner

def render_table(node, ctx):
    # simplistic table rendering
    rows = []
    for tr in node.children:
        if tr.tag == 'tr':
            row = []
            for td in tr.children:
                if td.tag in ['td', 'th']:
                    row.append(render_node(td, ctx).strip())
            if row:
                rows.append(row)
    if not rows:
        return ""
    res = ""
    res += "| " + " | ".join(rows[0]) + " |\n"
    res += "|" + "|".join("-" * (len(col) + 2) for col in rows[0]) + "|\n"
    for row in rows[1:]:
        res += "| " + " | ".join(row) + " |\n"
    return res + "\n"

class Context:
    def __init__(self, args):
        self.args = args

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--version", "-v", action="store_true")
    parser.add_argument("--help", action="store_true")
    parser.add_argument("--input")
    parser.add_argument("--output")
    parser.add_argument("--output-overwrite", action="store_true")
    parser.add_argument("--domain")
    parser.add_argument("--exclude-selector", action="append")
    parser.add_argument("--include-selector", action="append")
    parser.add_argument("--opt-strong-delimiter", default="**")
    parser.add_argument("--opt-table-cell-padding-behavior", default="aligned")
    parser.add_argument("--opt-table-header-promotion", action="store_true")
    parser.add_argument("--opt-table-newline-behavior", default="preserve")
    parser.add_argument("--opt-table-presentation-tables", action="store_true")
    parser.add_argument("--opt-table-skip-empty-rows", action="store_true")
    parser.add_argument("--opt-table-span-cell-behavior", default="mirror")
    parser.add_argument("--plugin-strikethrough", action="store_true")
    parser.add_argument("--plugin-table", action="store_true")

    args, unknown = parser.parse_known_args()

    if args.version:
        print("html2markdown\n\nGitVersion:  dev\nGitCommit:   none\nBuildDate:   unknown")
        sys.exit(0)

    if args.help:
        with open("help.txt") as f:
            print(f.read(), end="")
        sys.exit(0)

    ctx = Context(args)

    inputs = []
    if args.input:
        if "*" in args.input:
            inputs = glob.glob(args.input)
        elif os.path.isdir(args.input):
            inputs = [os.path.join(args.input, f) for f in os.listdir(args.input) if f.endswith(".html")]
        else:
            inputs = [args.input]
    else:
        # read from stdin
        html = sys.stdin.read()
        root = parse_html(html)
        md = render_node(root, ctx).strip()
        print(md)
        sys.exit(0)

    if not inputs:
        print(f"error: no files found matching pattern \"{args.input}\"")
        sys.exit(1)

    # handle outputs ...
