        data_rows = rows[1:]
    else:
        res += "| " + " | ".join("".ljust(col_widths[i]) for i in range(len(col_widths))) + " |\n"
        res += "|" + "|".join("-" * (col_widths[i] + 2) for i in range(len(col_widths))) + "|\n"
        data_rows = rows

    for r in data_rows:
        res += "| " + " | ".join(c.ljust(col_widths[i]) if i < len(r) else "".ljust(col_widths[i]) for i, c in enumerate(r)) + " |\n"

