#!/bin/bash
cat <<'PYEOF' > html2md.py
import argparse
import sys
import os
import glob
import re
from urllib.parse import urljoin
from html.parser import HTMLParser

HELP_TEXT = """
# html2markdown - convert html to markdown [version dev]

Convert HTML to Markdown. Even works with entire websites!

## Basics

By default the "Commonmark" Plugin will be enabled. You can customize the options,
for example changing the appearance of bold with --opt-strong-delimiter="__"

Other Plugins can also be enabled. For example "GitHub Flavored Markdown" (GFM)
extends Commonmark with more features.

## Relative / Absolute Links

Use --domain="https://example.com" to convert *relative* links to *absolute* links.
The same also works for images.

## Escaping

Some characters have a special meaning in markdown. The library escapes these — if necessary.
See the documentation for more info.

## Security

Once you convert this markdown *back* to HTML you need to be careful of malicious content. 
Use a HTML sanitizer before displaying the HTML in the browser!


## Examples

    echo "<strong>important</strong>" | html2markdown

    curl --no-progress-meter http://example.com | html2markdown


    html2markdown --input file.html --output file.md

    html2markdown --input "src/*.html" --output "dist/"


## Flags

    -v, --version
        show the version of html2markdown and exit

    --help

    --input PATH
        Input file, directory, or glob pattern (instead of stdin)

    --output PATH
        Output file or directory (instead of stdout)

    --output-overwrite
        Replace existing files

    If --input is a directory or glob pattern, --output must be a directory.



    --domain
        The url of the web page, used to convert relative links to absolute links.

    --exclude-selector
        css query selector to exclude parts of the input

    --include-selector
        css query selector to only include parts of the input

    --opt-strong-delimiter
        Make bold text. Should <strong> be indicated by two asterisks or two underscores?
        "**" or "__" (default: "**")

    --opt-table-cell-padding-behavior
        [for --plugin-table] whether cells in the tables should include extra padding for visual continuity: "aligned", "minimal", or "none"

    --opt-table-header-promotion
        [for --plugin-table] first row should be treated as a header

    --opt-table-newline-behavior
        [for --plugin-table] how tables containing newlines should be handled: "skip" or "preserve"

    --opt-table-presentation-tables
        [for --plugin-table] whether tables with role="presentation" should be converted

    --opt-table-skip-empty-rows
        [for --plugin-table] omit empty rows from the output

    --opt-table-span-cell-behavior
        [for --plugin-table] how colspan/rowspan should be rendered: "empty" or "mirror"

    --plugin-strikethrough
        enable the plugin ~~strikethrough~~

    --plugin-table
        enable the plugin table



For more information visit the documentation:
https://github.com/Johanneskaufmann/html-to-markdown
"""

VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}

class Node:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower() if tag else tag
        self.attrs = attrs or {}
        self.parent = parent
        self.children = []
    def add_child(self, node):
        self.children.append(node)

class TextNode(Node):
    def __init__(self, text, parent=None):
        super().__init__(None, None, parent)
        self.text = text

class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.root = Node(None)
        self.current = self.root

    def handle_starttag(self, tag, attrs):
        node = Node(tag, dict(attrs), self.current)
        self.current.add_child(node)
        if tag.lower() not in VOID_TAGS:
            self.current = node

    def handle_endtag(self, tag):
        tag = tag.lower()
        curr = self.current
        while curr and curr.tag != tag:
            curr = curr.parent
        if curr and curr.parent:
            self.current = curr.parent

    def handle_startendtag(self, tag, attrs):
        node = Node(tag, dict(attrs), self.current)
        self.current.add_child(node)

    def handle_data(self, data):
        self.current.add_child(TextNode(data, self.current))

def parse_html(html):
    p = Parser()
    p.feed(html)
    return p.root

def match_sel_str(node, sel):
    if sel.startswith('.'): return sel[1:] in node.attrs.get('class', '').split()
    if sel.startswith('#'): return sel[1:] == node.attrs.get('id')
    if '#' in sel:
        t, i = sel.split('#', 1)
        return node.tag == t and node.attrs.get('id') == i
    if '.' in sel:
        t, c = sel.split('.', 1)
        return node.tag == t and c in node.attrs.get('class', '').split()
    return node.tag == sel

def match_sel(node, sels):
    for sel in sels:
        if match_sel_str(node, sel): return True
    return False

def remove_excludes(node, excludes):
    new_children = []
    for c in node.children:
        if not isinstance(c, TextNode):
            if match_sel(c, excludes): continue
            remove_excludes(c, excludes)
        new_children.append(c)
    node.children = new_children

def find_includes(node, includes, res):
    if not isinstance(node, TextNode) and match_sel(node, includes):
        res.append(node)
    else:
        for c in node.children:
            if not isinstance(c, TextNode):
                find_includes(c, includes, res)

def escape_text(text, is_start_of_line=False):
    text = text.replace('\\', '\\\\').replace('`', '\\`').replace('*', '\\*').replace('_', '\\_').replace('[', '\\[')
    if is_start_of_line:
        for prefix in ['#', '+', '-']:
            if text.startswith(prefix): text = '\\' + text
        if text.startswith('1.'): text = text.replace('.', '\\.', 1)
        if text.startswith('>'): text = '&gt;' + text[1:]
    text = text.replace('<', '&lt;').replace('>', '&gt;')
    return text

def collapse_whitespace(text):
    text = re.sub(r'[\r\n]+', ' ', text)
    text = re.sub(r' +', ' ', text)
    return text

def render_node(node, ctx, list_level=0, in_table=False, is_start_of_line=False):
    if isinstance(node, TextNode):
        text = collapse_whitespace(node.text)
        if is_start_of_line: text = text.lstrip()
        if not text: return ""
        return escape_text(text, is_start_of_line)

    if node.tag in ['head', 'style', 'script', 'meta', 'link', 'title']: return ""

    inner_raw = []
    child_start_of_line = is_start_of_line
    for i, c in enumerate(node.children):
        if i == 0 and node.tag in ['p', 'li', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'td', 'th', 'blockquote', 'pre']:
            child_start_of_line = True
        inner_raw.append(render_node(c, ctx, list_level, in_table, child_start_of_line))
        child_start_of_line = False
    inner = "".join(inner_raw)

    if node.tag in ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']:
        level = int(node.tag[1])
        return f"{'#' * level} {inner.strip()}\n\n"

    if node.tag == 'p': return f"{inner.strip()}\n\n"

    if node.tag == 'br':
        if in_table and getattr(ctx.args, 'opt_table_newline_behavior', 'preserve') == 'preserve': return " <br />"
        if in_table and getattr(ctx.args, 'opt_table_newline_behavior', '') == 'skip': return "\n"
        return "  \n"

    if node.tag == 'hr': return "* * *\n\n"

    if node.tag in ['strong', 'b']:
        delim = getattr(ctx.args, 'opt_strong_delimiter', '**')
        sinner = inner.strip()
        if not sinner: return ""
        return f"{delim}{sinner}{delim}"

    if node.tag in ['em', 'i']:
        sinner = inner.strip()
        if not sinner: return ""
        return f"*{sinner}*"

    if node.tag == 'a':
        href = node.attrs.get('href', '')
        if getattr(ctx.args, 'domain', None) and not href.startswith(('http://', 'https://', 'mailto:', '#', '/')):
            href = urljoin(ctx.args.domain, href)
        elif getattr(ctx.args, 'domain', None) and href.startswith('/'):
            href = urljoin(ctx.args.domain, href)
        title = node.attrs.get('title')
        if title: return f"[{inner.strip()}]({href} \"{title}\")"
        return f"[{inner.strip()}]({href})"

    if node.tag == 'img':
        src = node.attrs.get('src', '')
        if getattr(ctx.args, 'domain', None) and not src.startswith(('http://', 'https://', 'data:', '/')):
            src = urljoin(ctx.args.domain, src)
        elif getattr(ctx.args, 'domain', None) and src.startswith('/'):
            src = urljoin(ctx.args.domain, src)
        alt = node.attrs.get('alt', '')
        title = node.attrs.get('title')
        if title: return f"![{alt}]({src} \"{title}\")"
        return f"![{alt}]({src})"

    if node.tag == 'code': return f"`{inner}`"

    if node.tag == 'pre':
        lang = ""
        if node.children and not isinstance(node.children[0], TextNode) and node.children[0].tag == 'code':
            cls = node.children[0].attrs.get('class', '')
            if cls.startswith('language-'): lang = cls[9:]
            lines = [c.text if isinstance(c, TextNode) else "" for c in node.children[0].children]
            code_inner = "".join(lines).strip('\r\n')
        else:
            lines = [c.text if isinstance(c, TextNode) else "" for c in node.children]
            code_inner = "".join(lines).strip('\r\n')
        return f"```{lang}\n{code_inner}\n```\n\n"

    if node.tag == 'blockquote':
        lines = inner.strip().split('\n')
        res = "\n".join(f"> {line}" if line else ">" for line in lines)
        return res + "\n\n"

    if node.tag == 'ul':
        res = ""
        for c in node.children:
            if not isinstance(c, TextNode) and c.tag == 'li':
                item_inner = render_node(c, ctx, list_level+1, in_table, True).strip()
                lines = item_inner.split('\n')
                res += f"- {lines[0]}\n"
                for line in lines[1:]: res += f"  {line}\n" if line.strip() else "\n"
        return res + "\n"

    if node.tag == 'ol':
        res = ""
        i = 1
        for c in node.children:
            if not isinstance(c, TextNode) and c.tag == 'li':
                item_inner = render_node(c, ctx, list_level+1, in_table, True).strip()
                lines = item_inner.split('\n')
                res += f"{i}. {lines[0]}\n"
                for line in lines[1:]: res += f"   {line}\n" if line.strip() else "\n"
                i += 1
        return res + "\n"

    if node.tag in ['del', 's', 'strike']:
        if getattr(ctx.args, 'plugin_strikethrough', False): return f"~~{inner.strip()}~~"
        return inner

    if node.tag == 'table':
        if node.attrs.get('role') == 'presentation' and not getattr(ctx.args, 'opt_table_presentation_tables', False):
            return inner.strip() + "\n\n"
        if not getattr(ctx.args, 'plugin_table', False):
            return inner.strip() + "\n\n"
        if getattr(ctx.args, 'opt_table_newline_behavior', 'preserve') == 'skip' and '\n' in inner:
            return inner.strip() + "\n\n"
        return render_table(node, ctx) + "\n"

    return inner

def render_table(node, ctx):
    rows = []
    def extract_row(tr):
        row = []
        for c in tr.children:
            if not isinstance(c, TextNode) and c.tag in ['td', 'th']:
                row.append(render_node(c, ctx, in_table=True, is_start_of_line=True).strip())
        return row

    for c in node.children:
        if not isinstance(c, TextNode):
            if c.tag == 'tr':
                r = extract_row(c)
                if r or not getattr(ctx.args, 'opt_table_skip_empty_rows', False): rows.append(r)
            elif c.tag in ['thead', 'tbody', 'tfoot']:
                for tr in c.children:
                    if not isinstance(tr, TextNode) and tr.tag == 'tr':
                        r = extract_row(tr)
                        if r or not getattr(ctx.args, 'opt_table_skip_empty_rows', False): rows.append(r)

    if not rows: return ""
    col_widths = []
    for r in rows:
        for i, c in enumerate(r):
            if i >= len(col_widths): col_widths.append(len(c))
            else: col_widths[i] = max(col_widths[i], len(c))

    if not col_widths: return ""

    res = ""
    header = rows[0]
    has_th = False

    first_tr = None
    for c in node.children:
        if not isinstance(c, TextNode):
            if c.tag == 'tr': first_tr = c; break
            elif c.tag == 'thead':
                for tr in c.children:
                    if not isinstance(tr, TextNode) and tr.tag == 'tr': first_tr = tr; break
                break

    if first_tr:
        for c in first_tr.children:
            if not isinstance(c, TextNode) and c.tag == 'th': has_th = True; break

    if not has_th and getattr(ctx.args, 'opt_table_header_promotion', False):
        has_th = True

    if has_th:
        res += "| " + " | ".join(h.ljust(col_widths[i]) for i, h in enumerate(header)) + " |\n"
        res += "|" + "|".join("-" * (col_widths[i] + 2) for i in range(len(col_widths))) + "|\n"
        data_rows = rows[1:]
    else:
        res += "| " + " | ".join("".ljust(col_widths[i]) for i in range(len(col_widths))) + " |\n"
        res += "|" + "|".join("-" * (col_widths[i] + 2) for i in range(len(col_widths))) + "|\n"
        data_rows = rows

    for r in data_rows:
        res += "| " + " | ".join(c.ljust(col_widths[i]) if i < len(r) else "".ljust(col_widths[i]) for i, c in enumerate(r)) + " |\n"

    return res

class Context:
    def __init__(self, args):
        self.args = args

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--version", "-v", action="store_true")
    parser.add_argument("--help", action="store_true")
    parser.add_argument("--input")
    parser.add_argument("--output")
    parser.add_argument("--output-overwrite", action="store_true")
    parser.add_argument("--domain")
    parser.add_argument("--exclude-selector", action="append")
    parser.add_argument("--include-selector", action="append")
    parser.add_argument("--opt-strong-delimiter", default="**")
    parser.add_argument("--opt-table-cell-padding-behavior", default="aligned")
    parser.add_argument("--opt-table-header-promotion", action="store_true")
    parser.add_argument("--opt-table-newline-behavior", default="preserve")
    parser.add_argument("--opt-table-presentation-tables", action="store_true")
    parser.add_argument("--opt-table-skip-empty-rows", action="store_true")
    parser.add_argument("--opt-table-span-cell-behavior", default="mirror")
    parser.add_argument("--plugin-strikethrough", action="store_true")
    parser.add_argument("--plugin-table", action="store_true")

    args, unknown = parser.parse_known_args()

    if args.version:
        print("html2markdown\n\nGitVersion:  dev\nGitCommit:   none\nBuildDate:   unknown")
        sys.exit(0)

    if args.help:
        print(HELP_TEXT, end="")
        sys.exit(0)

    ctx = Context(args)

    inputs = []
    if args.input:
        if "*" in args.input:
            inputs = glob.glob(args.input)
        elif os.path.isdir(args.input):
            inputs = [os.path.join(args.input, f) for f in os.listdir(args.input) if f.endswith(".html")]
        else:
            inputs = [args.input]
    else:
        if sys.stdin.isatty():
            print("error: the html input should be piped into the cli\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n")
            sys.exit(1)

        html = sys.stdin.read()
        root = parse_html(html)
        if args.exclude_selector: remove_excludes(root, args.exclude_selector)
        if args.include_selector:
            inc_nodes = []
            find_includes(root, args.include_selector, inc_nodes)
            root = Node(None)
            root.children = inc_nodes

        md = render_node(root, ctx).strip()
        md = re.sub(r'\n{3,}', '\n\n', md)

        if args.output:
            if not args.output_overwrite and os.path.exists(args.output):
                print(f"error: output path \"{args.output}\" already exists. Use --output-overwrite to replace existing files\n")
                sys.exit(1)
            with open(args.output, "w") as f:
                f.write(md + "\n")
        else:
            print(md)
        sys.exit(0)

    if not inputs:
        print(f"error: no files found matching pattern \"{args.input}\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n")
        sys.exit(1)

    if len(inputs) > 1 and args.output and not args.output.endswith('/'):
        print(f"error: when processing multiple input files, --output \"{args.output}\" must end with \"{args.output}/\" to indicate a directory\n")
        sys.exit(1)

    for f in inputs:
        with open(f) as file:
            html = file.read()
        root = parse_html(html)

        if args.exclude_selector: remove_excludes(root, args.exclude_selector)
        if args.include_selector:
            inc_nodes = []
            find_includes(root, args.include_selector, inc_nodes)
            root = Node(None)
            root.children = inc_nodes

        md = render_node(root, ctx, is_start_of_line=True).strip()
        md = re.sub(r'\n{3,}', '\n\n', md)

        if args.output:
            outpath = args.output
            if args.output.endswith('/'):
                os.makedirs(args.output, exist_ok=True)
                base = os.path.basename(f)
                name, ext = os.path.splitext(base)
                outpath = os.path.join(args.output, name + ".md")
            else:
                outpath = args.output

            if not args.output_overwrite and os.path.exists(outpath):
                print(f"error: output path \"{outpath}\" already exists. Use --output-overwrite to replace existing files\n")
                sys.exit(1)

            with open(outpath, "w") as f_out:
                f_out.write(md + "\n")
        else:
            print(md)

if __name__ == "__main__":
    main()
